import{_ as e,o as n,c as i,a0 as a}from"./chunks/framework.DScjKhBS.js";const r=""+new URL("../report/agency-lifecycle-02-pain-points.png",import.meta.url).href,h=JSON.parse('{"title":"Pain Points and Waste Map","description":"Where time, quality, and margin are lost in a standard agency project flow — phase by phase.","frontmatter":{"title":"Pain Points and Waste Map","description":"Where time, quality, and margin are lost in a standard agency project flow — phase by phase."},"headers":[],"relativePath":"reports/agency-project-lifecycle/02-pain-points.md","filePath":"reports/agency-project-lifecycle/02-pain-points.md"}'),s={name:"reports/agency-project-lifecycle/02-pain-points.md"};function o(d,t,l,c,g,p){return n(),i("div",null,[...t[0]||(t[0]=[a('<figure class="report-section-image-wrapper" aria-labelledby="fig-pain-points-caption"><img src="'+r+'" alt="Pipeline with cracks and leaks at estimation, content, and spec phases" loading="lazy" class="report-section-image"><figcaption id="fig-pain-points-caption">Pipeline with cracks and leaks at estimation, content, and spec phases</figcaption></figure><h1 id="_2-pain-points-and-waste-map" tabindex="-1">2. Pain Points and Waste Map <a class="header-anchor" href="#_2-pain-points-and-waste-map" aria-label="Permalink to &quot;2. Pain Points and Waste Map&quot;">​</a></h1><p>Before looking at solutions, it is worth mapping where agencies typically lose time, quality, or margin. These are the structural problems that exist regardless of team skill — they are process failures, not people failures.</p><h2 id="summary-heat-map" tabindex="-1">Summary Heat Map <a class="header-anchor" href="#summary-heat-map" aria-label="Permalink to &quot;Summary Heat Map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Phase</th><th style="text-align:center;">Time Waste</th><th style="text-align:center;">Quality Risk</th><th style="text-align:center;">Margin Erosion</th><th>Notes</th></tr></thead><tbody><tr><td>1. Estimation</td><td style="text-align:center;">High</td><td style="text-align:center;">Medium</td><td style="text-align:center;"><strong>Critical</strong></td><td>Under-scoping, hidden hours, new-client uncertainty</td></tr><tr><td>2. Discovery</td><td style="text-align:center;">Medium</td><td style="text-align:center;">Medium</td><td style="text-align:center;">Low</td><td>Skipped or compressed; intent not captured precisely</td></tr><tr><td>3. IA &amp; Content Plan</td><td style="text-align:center;">Medium</td><td style="text-align:center;">High</td><td style="text-align:center;">Medium</td><td>Done too late or too loosely; content gaps surface in build</td></tr><tr><td>4. UX/UI Design</td><td style="text-align:center;">Medium</td><td style="text-align:center;">Medium</td><td style="text-align:center;">High</td><td>Revision loops; subjective feedback without anchoring</td></tr><tr><td>5. Technical Spec</td><td style="text-align:center;">Low–Medium</td><td style="text-align:center;"><strong>Critical</strong></td><td style="text-align:center;">Medium</td><td>Often informal or skipped; leads to rework in build</td></tr><tr><td>6. Build</td><td style="text-align:center;">Medium</td><td style="text-align:center;">High</td><td style="text-align:center;">High</td><td>Rework from upstream gaps; scope creep; integration surprises</td></tr><tr><td>7. Content Population</td><td style="text-align:center;"><strong>Critical</strong></td><td style="text-align:center;">High</td><td style="text-align:center;"><strong>Critical</strong></td><td>Client dependency; manual repetitive work; launch blocker</td></tr><tr><td>8. QA &amp; Testing</td><td style="text-align:center;">Medium</td><td style="text-align:center;">High</td><td style="text-align:center;">Medium</td><td>Compressed; bugs found late; accessibility/performance bolted on</td></tr><tr><td>9. Training</td><td style="text-align:center;">Low</td><td style="text-align:center;">Medium</td><td style="text-align:center;">Low</td><td>Rushed or generic; client cannot self-serve after launch</td></tr><tr><td>10. Launch</td><td style="text-align:center;">Low</td><td style="text-align:center;">Medium</td><td style="text-align:center;">Low</td><td>Checklist gaps; missed redirects; analytics not validated</td></tr><tr><td>11. Post-Launch</td><td style="text-align:center;">Low</td><td style="text-align:center;">Medium</td><td style="text-align:center;">Medium</td><td>No governance plan; site quality degrades over time</td></tr></tbody></table><hr><h2 id="phase-by-phase-breakdown" tabindex="-1">Phase-by-Phase Breakdown <a class="header-anchor" href="#phase-by-phase-breakdown" aria-label="Permalink to &quot;Phase-by-Phase Breakdown&quot;">​</a></h2><h3 id="_1-estimation-and-scoping" tabindex="-1">1. Estimation and Scoping <a class="header-anchor" href="#_1-estimation-and-scoping" aria-label="Permalink to &quot;1. Estimation and Scoping&quot;">​</a></h3><p><strong>Core problems:</strong></p><ul><li><strong>Under-scoping hidden hours.</strong> PM, communication, meetings, and QA typically add 25–40% to raw delivery time but are routinely under-estimated or omitted from proposals.</li><li><strong>Optimism bias.</strong> Estimates are based on best-case scenarios. Industry guidance suggests adding 20% for new clients, 15% for new project types, 10% for tight deadlines — but few agencies apply these multipliers systematically.</li><li><strong>No historical data.</strong> Most agencies estimate from gut feel rather than from time-tracking data on comparable past projects. Estimates are inconsistent across estimators.</li><li><strong>Binary pricing under uncertainty.</strong> Fixed-price proposals lock in a number before the real scope is understood. T&amp;M avoids this but shifts risk to the client.</li><li><strong>Speed pressure.</strong> Proposals are often produced in hours, not days. There is no time for proper technical review.</li></ul><p><strong>Downstream effect:</strong> Margin erosion is the single largest commercial risk. An under-scoped project loses money from day one.</p><h3 id="_2-briefing-and-discovery" tabindex="-1">2. Briefing and Discovery <a class="header-anchor" href="#_2-briefing-and-discovery" aria-label="Permalink to &quot;2. Briefing and Discovery&quot;">​</a></h3><p><strong>Core problems:</strong></p><ul><li><strong>Discovery treated as overhead.</strong> Clients (and some agencies) see discovery as time before &quot;real work&quot; starts and compress it.</li><li><strong>Intent not captured precisely.</strong> Goals and success criteria are described in vague, qualitative terms (&quot;make it modern&quot;, &quot;improve engagement&quot;) rather than measurable outcomes.</li><li><strong>Stakeholder misalignment surfaces late.</strong> Approval authority and decision-making are not mapped until conflict arises during design review.</li><li><strong>Technical constraints not surfaced.</strong> Hosting, integrations, third-party dependencies, and data constraints are not investigated until the build phase.</li></ul><p><strong>Downstream effect:</strong> Vague discovery produces vague specs, which produces subjective feedback loops in design and rework in build.</p><h3 id="_3-ia-and-content-planning" tabindex="-1">3. IA and Content Planning <a class="header-anchor" href="#_3-ia-and-content-planning" aria-label="Permalink to &quot;3. IA and Content Planning&quot;">​</a></h3><p><strong>Core problems:</strong></p><ul><li><strong>Content planning happens too late.</strong> Many agencies design layouts before content direction exists, then retrofit content into fixed containers.</li><li><strong>Content responsibility is unclear.</strong> &quot;Client provides content&quot; is a common assumption, but the client often does not have content ready, does not know what format is needed, or does not understand the volume required.</li><li><strong>Page intent is not defined.</strong> Pages are listed in a sitemap but their purpose, primary message, and expected user action are not specified.</li><li><strong>SEO is bolted on.</strong> Keyword mapping, URL structure, and redirect planning happen after IA is finalised, leading to retrofits.</li></ul><p><strong>Downstream effect:</strong> Content gaps are the number one cause of launch delays. Late or missing content forces design compromises and QA rework.</p><h3 id="_4-ux-ui-design" tabindex="-1">4. UX/UI Design <a class="header-anchor" href="#_4-ux-ui-design" aria-label="Permalink to &quot;4. UX/UI Design&quot;">​</a></h3><p><strong>Core problems:</strong></p><ul><li><strong>Subjective feedback loops.</strong> Without anchored goals and content direction, design review becomes opinion-based. Revisions multiply.</li><li><strong>States and edge cases missed.</strong> Error states, empty states, loading states, long-title handling, and mobile behaviour are not specified until development discovers them.</li><li><strong>Design-to-dev handoff is lossy.</strong> Spacing, responsive breakpoints, interaction behaviour, and component variants are under-specified in design files. Developers interpret or guess.</li><li><strong>Accessibility as afterthought.</strong> Contrast, focus management, and semantic structure are not checked in design QA; they surface as bugs in testing.</li></ul><p><strong>Downstream effect:</strong> Each extra revision round costs 5–10% of design budget. Lossy handoff causes rework in build.</p><h3 id="_5-technical-specification" tabindex="-1">5. Technical Specification <a class="header-anchor" href="#_5-technical-specification" aria-label="Permalink to &quot;5. Technical Specification&quot;">​</a></h3><p><strong>Core problems:</strong></p><ul><li><strong>Often informal or skipped entirely.</strong> Many agencies go straight from design sign-off to &quot;start building.&quot; The technical plan exists only in the developer&#39;s head.</li><li><strong>No shared format.</strong> Where specs do exist, they vary by author and are not structured consistently — making them hard to review and easy to miss.</li><li><strong>Integration complexity is underestimated.</strong> Third-party APIs, CRM integrations, and search are scoped as single line items but consume disproportionate build time.</li><li><strong>Content model not documented.</strong> CMS architecture (content types, fields, relationships) is defined on the fly during build rather than planned.</li></ul><p><strong>Downstream effect:</strong> Lack of spec is the root cause of most build-phase rework. The <a href="./reports/dark-factory/">Dark Factory</a> and <a href="./reports/structured-prompt-driven/">SPDD</a> reports address this directly.</p><h3 id="_6-build-development" tabindex="-1">6. Build (Development) <a class="header-anchor" href="#_6-build-development" aria-label="Permalink to &quot;6. Build (Development)&quot;">​</a></h3><p><strong>Core problems:</strong></p><ul><li><strong>Rework from upstream gaps.</strong> Missing specs, changing designs, late content requirements, and undocumented integrations cause rebuilds.</li><li><strong>Scope creep.</strong> &quot;While you&#39;re at it…&quot; requests accumulate. Without a clear spec to reference, it is hard to distinguish in-scope from out-of-scope.</li><li><strong>Component duplication.</strong> Without a documented design system, developers build slight variations of the same component.</li><li><strong>Performance and accessibility not checked during build.</strong> Problems accumulate and are expensive to fix in QA.</li><li><strong>PR review bottleneck.</strong> On small teams, a single reviewer can become a throughput constraint (addressed in <a href="./reports/pr-review-continuity/">PR Review Continuity</a>).</li></ul><p><strong>Downstream effect:</strong> Build is the largest cost centre. Upstream failures compound here.</p><h3 id="_7-content-population-and-migration" tabindex="-1">7. Content Population and Migration <a class="header-anchor" href="#_7-content-population-and-migration" aria-label="Permalink to &quot;7. Content Population and Migration&quot;">​</a></h3><p><strong>Core problems:</strong></p><ul><li><strong>Manual, repetitive, low-value work.</strong> Entering content into a CMS page-by-page is time-consuming and error-prone. For large sites (hundreds or thousands of pages), this is the biggest single time sink.</li><li><strong>Client dependency.</strong> The agency cannot populate content the client has not provided. Chasing content is a PM overhead.</li><li><strong>Migration complexity.</strong> Redesigns require mapping old content to new structures. Legacy content (shortcodes, custom fields, non-standard markup) causes edge cases.</li><li><strong>SEO metadata as afterthought.</strong> Titles, descriptions, alt text, and structured data are entered last or forgotten.</li><li><strong>No quality gate.</strong> Content accuracy, tone, and completeness are reviewed informally if at all.</li></ul><p><strong>Downstream effect:</strong> Content population is the most common cause of launch delays. It is also the phase with the worst ratio of time spent to value delivered.</p><h3 id="_8-qa-and-testing" tabindex="-1">8. QA and Testing <a class="header-anchor" href="#_8-qa-and-testing" aria-label="Permalink to &quot;8. QA and Testing&quot;">​</a></h3><p><strong>Core problems:</strong></p><ul><li><strong>Compressed timeline.</strong> QA is the first phase to be squeezed when earlier phases overrun.</li><li><strong>Late bug discovery.</strong> Issues that should have been caught in design QA or during build surface here at higher fix cost.</li><li><strong>Inconsistent coverage.</strong> Without a test plan, QA coverage depends on the tester&#39;s experience and time pressure.</li><li><strong>Accessibility bolted on.</strong> WCAG compliance is tested for the first time in QA rather than validated during design and build.</li><li><strong>Performance tested too late.</strong> Core Web Vitals failures discovered in QA require architectural changes, not quick fixes.</li></ul><p><strong>Downstream effect:</strong> Bugs found in QA cost 5–10x more to fix than bugs caught during build. Compressed QA means bugs ship.</p><h3 id="_9-client-training" tabindex="-1">9. Client Training <a class="header-anchor" href="#_9-client-training" aria-label="Permalink to &quot;9. Client Training&quot;">​</a></h3><p><strong>Core problems:</strong></p><ul><li><strong>Generic, not project-specific.</strong> Training covers CMS basics rather than the specific content model, components, and workflows built for the client.</li><li><strong>No reusable documentation.</strong> Training is live only; when the attendee forgets or leaves, knowledge is lost.</li><li><strong>Component misuse.</strong> Clients do not understand which components to use where, leading to layout breakage and design drift post-launch.</li><li><strong>Compressed or skipped.</strong> Training is scheduled in the final week and often shortened when the project is running late.</li></ul><p><strong>Downstream effect:</strong> Poor training creates a support burden and accelerates site quality degradation.</p><h3 id="_10-delivery-and-launch" tabindex="-1">10. Delivery and Launch <a class="header-anchor" href="#_10-delivery-and-launch" aria-label="Permalink to &quot;10. Delivery and Launch&quot;">​</a></h3><p><strong>Core problems:</strong></p><ul><li><strong>Checklist gaps.</strong> Redirects, analytics validation, caching, CDN, and security headers are sometimes missed.</li><li><strong>No smoke test protocol.</strong> Post-launch verification is ad-hoc rather than scripted.</li><li><strong>Communication gaps.</strong> Client stakeholders are not always briefed on what &quot;live&quot; means and what is their responsibility afterwards.</li></ul><p><strong>Downstream effect:</strong> Launch issues are visible and high-pressure. A missed redirect or broken form erodes client trust disproportionately.</p><h3 id="_11-post-launch-support-and-governance" tabindex="-1">11. Post-Launch Support and Governance <a class="header-anchor" href="#_11-post-launch-support-and-governance" aria-label="Permalink to &quot;11. Post-Launch Support and Governance&quot;">​</a></h3><p><strong>Core problems:</strong></p><ul><li><strong>No governance plan.</strong> Content publishing standards, component usage rules, and performance monitoring are not documented.</li><li><strong>Site quality degrades.</strong> Without governance, new content breaks layouts, images are uploaded unoptimised, and third-party scripts are added without performance review.</li><li><strong>Reactive support.</strong> The agency fixes things when they break rather than monitoring proactively.</li><li><strong>No feedback loop.</strong> Lessons from post-launch are not systematically captured and fed back into estimation and discovery for the next project.</li></ul><p><strong>Downstream effect:</strong> The site the agency launches is not the site the client has six months later. Governance is the missing link between delivery and long-term value.</p><hr><h2 id="where-the-money-goes" tabindex="-1">Where the Money Goes <a class="header-anchor" href="#where-the-money-goes" aria-label="Permalink to &quot;Where the Money Goes&quot;">​</a></h2><p>If a typical mid-sized build is 600 hours:</p><table tabindex="0"><thead><tr><th>Phase</th><th>% of hours</th><th>Hours</th><th>Waste risk</th></tr></thead><tbody><tr><td>Estimation</td><td>2%</td><td>~12</td><td>Margin set here; errors are permanent</td></tr><tr><td>Discovery</td><td>5%</td><td>~30</td><td>Compressed = rework later</td></tr><tr><td>IA / Content plan</td><td>5%</td><td>~30</td><td>Skipped = content delays</td></tr><tr><td>Design</td><td>20%</td><td>~120</td><td>Revision loops</td></tr><tr><td>Technical spec</td><td>5%</td><td>~30</td><td>Skipped = rework in build</td></tr><tr><td>Build</td><td>35%</td><td>~210</td><td>Upstream failures compound</td></tr><tr><td>Content population</td><td>10%</td><td>~60</td><td>Manual, client-dependent</td></tr><tr><td>QA</td><td>10%</td><td>~60</td><td>Compressed, late bugs</td></tr><tr><td>Training</td><td>2%</td><td>~12</td><td>Rushed</td></tr><tr><td>Launch</td><td>2%</td><td>~12</td><td>Checklist execution</td></tr><tr><td>Post-launch</td><td>4%</td><td>~24</td><td>Often unbilled</td></tr></tbody></table><p>The phases with the highest waste risk relative to their size: <strong>estimation</strong> (sets the margin), <strong>content population</strong> (blocks launch), and <strong>technical spec</strong> (determines build efficiency).</p>',56)])])}const m=e(s,[["render",o]]);export{h as __pageData,m as default};
